use vstd::prelude::*;

// Verus function to count the number of true elements in an array,
// with full verification that the result is between 0 and arr.len(),
// equals the formal count of true elements,
// and that the loop invariant captures correctness at every prefix.
verus! {

    // Formal specification function: counts number of true elements in the slice arr[..n]
    spec fn count_true_spec(arr: Seq<bool>, n: nat) -> nat {
        if n == 0 { 0 } else {
            count_true_spec(arr, n - 1) + (if arr[n - 1] { 1 } else { 0 })
        }
    }

    #[verifier(external_body)]
    fn count_true(arr: &Vec<bool>) -> (count: u64)
        ensures
            count as usize <= arr.len(), 
            count as usize == count_true_spec(arr.to_seq(), arr.len()),
    {
        let mut i: usize = 0;
        let mut acc: u64 = 0;

        // Loop invariant: 
        // 1) 0 <= i <= arr.len()
        // 2) acc equals the formal count of true values in arr[0..i]
        while i < arr.len() 
            invariant i <= arr.len()
            invariant acc as usize == count_true_spec(arr.to_seq(), i)
            decreases arr.len() - i
        {
            if arr[i] {
                acc = acc + 1;
            }
            i = i + 1;
        }

        acc
    }
}